public class METPopulateReports
{
    public static const str kpmgSalesInvoiceReport = 'KPMGSalesInvoice.Report';

}

Method.Source:
/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    #PrintMgmtSetup


    PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::SalesOrderInvoice, ssrsReportStr(METSalesInvoice, Report), ssrsReportStr(METSalesInvoice, Report), #NoCountryRegionId, true);

    PrintMgmtReportFormat printMgmtReportFormat;

    ttsbegin;
    update_recordSet printMgmtReportFormat
        setting System = false
        where printMgmtReportFormat.DocumentType == PrintMgmtDocumentType::SalesOrderInvoice
        && printMgmtReportFormat.Description == METPopulateReports::kpmgSalesInvoiceReport
            && printMgmtReportFormat.CountryRegionId == #NoCountryRegionId
            && printMgmtReportFormat.System == true;
    ttscommit;

}
